const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
let lead_email='', manual=false;
try{ const li=$('Live Input').first().json; lead_email=li.lead_email||''; }catch(e){}
try{ const mi=$('Manual Input').first().json; if(mi){ lead_email=lead_email||mi.lead_email||''; manual=(mi.manual===true||mi.manual==='true'); } }catch(e){}
const r=$('Find Client Row').first().json||{};
const f=r.fields||r;
const name=f['Client']||'';
// The qualification rubric is read by Enrich and Qualify Lead (KB Files, Type=qualification-prompt);
// Qualify Input passes the legacy Clients field 'Qualification Prompt' as that helper's fallback.
return [{ json: {
  lead_email: lead_email,
  manual: manual,
  recordId: r.id||'',
  clientName: name,
  clientSlug: String(name).toLowerCase().replace(/[^a-z0-9]/g,''),
  pvWorkspace: f['PlusVibe Workspace ID']||'',
  slackChannel: f['Slack Channel ID']||'',
  driveFolder: f['driveMainFolderID']||'',
  clayrootsBase: f['Clayroots Base ID']||'',
  notifyGoalLine: f['Notify Goal Line']||''
}}];

const raw=$input.first().json;
const rec=Array.isArray(raw)?raw[0]:(raw.lead_data?raw:(raw[0]||raw));
const d=(rec&&rec.lead_data)?rec.lead_data:(rec||{});
const first=d.first_name||'';
const email=(d.email||'').toLowerCase();
const rawDomain=String(d.domain||email.split('@')[1]||'').toLowerCase();
const FREEMAIL=new Set(['gmail.com','googlemail.com','yahoo.com','yahoo.ca','yahoo.co.uk','ymail.com','rocketmail.com','hotmail.com','hotmail.ca','hotmail.co.uk','outlook.com','outlook.ca','live.com','live.ca','msn.com','icloud.com','me.com','mac.com','aol.com','protonmail.com','proton.me','gmx.com','gmx.net','zoho.com','mail.com','yandex.com','comcast.net','verizon.net','att.net','sbcglobal.net','bellsouth.net','cox.net','charter.net','earthlink.net','bell.net','sympatico.ca','rogers.com','rogers.ca','shaw.ca','telus.net','cogeco.ca','videotron.ca','videotron.qc.ca','nbnet.nb.ca','frontier.com','windstream.net','optonline.net','roadrunner.com','rr.com','walla.com','walla.co.il']);
const is_freemail=FREEMAIL.has(rawDomain);
let webhookCampaign='';
try{ webhookCampaign=$('Live Input').first().json.pv_campaign_name||''; }catch(e){}
return [{ json: {
  lead_email:d.email||'', campaign_id:d.campaign_id||'',
  campaign_name: webhookCampaign||d.campaign_name||'',
  domain:rawDomain, enrich_domain:is_freemail?'':rawDomain, is_freemail:is_freemail,
  first_name:first, last_name:d.last_name||'', full_name:((first)+' '+(d.last_name||'')).trim(),
  job_title:d.job_title||'', company_name:d.company_name||'',
  linkedin_url:d.linkedin_person_url||'',
  city:d.city||'', state:d.state||'', country_code:d.country_code||'',
  existing_brief:d.custom_qualification_brief||'',
  sending_inbox:d.email_account_name||'', email_account_id:d.email_account_id||'',
  is_contact:(first.length>0)
}}];

const items=$input.all();
const leadEmail=($('Normalize').first().json.lead_email||'').toLowerCase();
const pool=[];
for(const it of items){ const r=(it&&it.json)||{}; const arr=r.data||r.emails||[]; if(Array.isArray(arr)) pool.push(...arr); }
const matched=pool.filter(m=>String(m.lead||'').toLowerCase()===leadEmail);
const use=matched.length?matched:pool;
const seen=new Set(); const uniq=[];
for(const m of use){ const k=m.message_id||m.id||JSON.stringify([m.sent_on,m.subject]); if(!seen.has(k)){ seen.add(k); uniq.push(m); } }
const fmtTs=(ts)=>{const d=new Date(ts);if(isNaN(d.getTime()))return '';return d.toLocaleString('sv-SE',{timeZone:'Asia/Jerusalem'}).slice(0,16)+' IL';};
const rawBody=(m)=>{if(typeof m.text_body==='string'&&m.text_body.trim())return m.text_body;let h='';if(m.body&&typeof m.body==='object')h=(typeof m.body.text==='string'&&m.body.text.trim())?m.body.text:(m.body.html||'');else if(typeof m.body==='string')h=m.body;else h=m.snippet||'';h=h.replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<br\s*\/?>/gi,'\n').replace(/<\/(?:p|div|tr|li|h[1-6])>/gi,'\n\n').replace(/<[^>]*>/g,' ');return h;};
const clean=(t)=>{
if(!t)return '';
let s=String(t).replace(/\r\n?/g,'\n');
s=s.replace(/(?:\n|^)[ \t]*-{3,}\s*Original Message\s*-{3,}[\s\S]*$/i,'');
s=s.replace(/(?:\n|^)[ \t]*_{10,}[\s\S]*$/,'');
s=s.replace(/(?:\n|\s)On\s+\S[\s\S]{0,170}?wrote:[\s\S]*$/i,'');
s=s.replace(/\n\s*>[\s\S]*$/,'');
s=s.replace(/(?:\n|^)From:\s[\s\S]*$/i,'');
s=s.replace(/(?:\n|^)[ \t]*Sent from my [^\n]*[\s\S]*$/i,'');
s=s.replace(/[a-z]+\\?:\s*\{behavior:url\([^)]*\)[^}]*\}/gi,'');
s=s.replace(/[.#]?[a-z][\w-]*\s*\{[^}]*\}/gi,'');
s=s.replace(/&nbsp;/gi,' ').replace(/&[a-z#0-9]+;/gi,' ');
const SIGOFF=/^(?:thanks|thank you|thanks so much|many thanks|regards|best regards|kind regards|warm regards|best|cheers|sincerely|all the best|talk soon|speak soon)[,!.]*$/i;
const TITLE=/\b(?:ceo|cto|coo|cfo|cmo|cro|cpo|vp|svp|evp|president|founder|co-?founder|director|manager|head of|partner|principal|engineer|consultant|advisor|owner|officer|chief)\b/i;
const URLISH=/(?:https?:\/\/|www\.|\b[a-z0-9-]+\.(?:com|net|org|io|ai|co|dev|app)\b)/i;
const lines=s.split('\n');
const looksSig=(i)=>{let score=0;let shorts=0;for(let j=i+1;j<Math.min(lines.length,i+7);j++){const L=lines[j].trim();if(!L)continue;const dg=L.replace(/\D/g,'').length;if(dg>=9&&dg<=15&&/[\d)]/.test(L))score+=2;if(URLISH.test(L))score+=2;if(TITLE.test(L))score+=2;if(L.length<=40)shorts++;}if(shorts>=2)score+=2;return score>=2;};
let cut=-1;
for(let i=0;i<lines.length;i++){const L=lines[i].trim();if(/^--\s*$/.test(L)){cut=i;break;}if(SIGOFF.test(L)&&looksSig(i)){cut=i;break;}}
if(cut>0)s=lines.slice(0,cut).join('\n');
s=s.split('\n').map(x=>x.replace(/[^\S\n]+/g,' ').trim()).join('\n');
s=s.replace(/\n{3,}/g,'\n\n');
return s.trim();
};
const fromOf=(m)=>{if(typeof m.from==='string')return m.from;if(Array.isArray(m.from_address_json)&&m.from_address_json[0])return m.from_address_json[0].address||'';return m.from_address_email||m.from_email||'';};
const isIn=(m)=>{if(m.current_step!==undefined)return false;const d=String(m.direction||'').toUpperCase();if(d==='IN')return true;if(d==='OUT')return false;return fromOf(m).toLowerCase().includes(leadEmail);};
const tsOf=(m)=>m.sent_on||m.timestamp_created||m.created_at||'';
const sorted=uniq.sort((a,b)=>new Date(tsOf(a))-new Date(tsOf(b)));
const blocks=[];
for(const m of sorted){
  const body=clean(rawBody(m));
  if(body.length<2) continue;
  const dir=isIn(m)?'THEM':'US';
  const t=tsOf(m);
  blocks.push('**['+fmtTs(t)+'] '+dir+':**\n'+body);
}
let thread_context=blocks.join('\n\n');
if(thread_context.length>50000)thread_context=thread_context.slice(-50000);
if(!thread_context)thread_context='No prior thread found.';
const inbound=sorted.filter(isIn);
const reply_text=inbound.length?clean(rawBody(inbound[inbound.length-1])).slice(0,2000):'';
const lastIn=inbound.length?inbound[inbound.length-1]:null;
let reply_at='';
if(lastIn){ const t=tsOf(lastIn); const d=new Date(t); if(t && !isNaN(d.getTime())) reply_at=d.toISOString(); }
const rawInbound=lastIn?String(rawBody(lastIn)||'').replace(/\r\n?/g,'\n'):'';
const SIGSTART=/^(?:--\s*|(?:thanks|thank you|thanks so much|many thanks|regards|best regards|kind regards|warm regards|best|cheers|sincerely|all the best|talk soon|speak soon)[,!.]*\s*)$/i;
const sigRegion=(raw)=>{ const L=String(raw||'').split('\n'); for(let i=0;i<L.length;i++){ if(SIGSTART.test(L[i].trim())) return L.slice(i).join('\n'); } return L.slice(Math.max(0,L.length-8)).join('\n'); };
const grabPhones=(txt)=>{ const out=[]; const re=/(?:\+?\d{1,3}[\t .\-]?)?(?:\(?\d{2,4}\)?[\t .\-]?){2,4}\d{2,4}/g; let mm; while((mm=re.exec(String(txt||'')))!==null){ const raw=mm[0].trim(); const dg=raw.replace(/\D/g,''); if(dg.length>=9&&dg.length<=15) out.push({raw:raw,dg:dg}); } return out; };
const isTollFree=(dg)=>{ let x=String(dg||''); if(x.length===11&&x.charAt(0)==='1') x=x.slice(1); return x.length===10&&/^(?:800|833|844|855|866|877|888)/.test(x); };
const toE164=(raw,dg)=>{ const t=String(raw).trim(); if(t.charAt(0)==='+') return '+'+dg; if(dg.length===11&&dg.charAt(0)==='1') return '+'+dg; if(dg.length===10&&dg.charAt(0)!=='0') return '+1'+dg; return t; };
const allCand=grabPhones(rawInbound);
const cands=(allCand.length===1)?allCand:grabPhones(sigRegion(rawInbound));
let signature_phone=''; let signature_phone_tollfree='';
for(const c of cands){ if(isTollFree(c.dg)){ if(!signature_phone_tollfree) signature_phone_tollfree=toE164(c.raw,c.dg); } else { if(!signature_phone) signature_phone=toE164(c.raw,c.dg); } }
const lastOut=[...sorted].reverse().find(m=>!isIn(m));
const last_two=(lastOut?'US: '+clean(rawBody(lastOut)).slice(0,1500)+'\n\n':'')+'THEM: '+reply_text;
const sentPre=sorted.filter(m=>!isIn(m)&&(!reply_at||!tsOf(m)||new Date(tsOf(m))<=new Date(reply_at)));
const sentBlocks=[];
for(const m of sentPre){ const body=clean(rawBody(m)); if(body.length<2) continue; const subj=String(m.subject||m.email_subject||'').trim(); sentBlocks.push('['+fmtTs(tsOf(m))+']'+(subj?' Subject: '+subj:'')+'\n'+body); }
let sent_emails_text=sentBlocks.join('\n\n');
if(sent_emails_text.length>8000)sent_emails_text=sent_emails_text.slice(0,8000);
return [{ json: { thread_context, reply_text, last_two, reply_at, sent_emails_text, signature_phone, signature_phone_tollfree } }];

// Builds the passthrough item for Enrich and Qualify Lead (the contract is documented at the top of that
// helper's Build Prompt node): the lead as Normalize shaped it, the thread Format Thread cut, the client name
// that resolves the rubric. The rubric lookup, DiscoLike and the judge live in the helper.
const n = $('Normalize').first().json || {};
const cv = $('Client Vars').first().json || {};
const ft = $('Format Thread').first().json || {};
let fallback = '', peopleTable = '', companiesTable = '';
try { const cf = ((($('Find Client Row').first().json || {}).fields) || {}); fallback = String(cf['Qualification Prompt'] || ''); peopleTable = String(cf['ClayrootsPeopleTableID'] || '').trim(); companiesTable = String(cf['ClayrootsCompaniesTableID'] || '').trim(); } catch (e) { fallback = ''; peopleTable = ''; companiesTable = ''; }
const context = [
  'PROSPECT LATEST REPLY:\n' + (ft.reply_text || ''),
  'RECENT EXCHANGE (our last message, then their reply, use this to interpret short replies like "sure"/"yes"):\n' + (ft.last_two || '')
].join('\n\n');
return [{ json: {
  client_name: cv.clientName || '',
  clayroots_base: cv.clayrootsBase || '',
  clayroots_people_table: peopleTable,
  clayroots_companies_table: companiesTable,
  system_prompt_fallback: fallback,
  first_name: n.first_name || '', last_name: n.last_name || '', job_title: n.job_title || '',
  company_name: n.company_name || '', lead_email: n.lead_email || '', linkedin_url: n.linkedin_url || '',
  domain: n.domain || '', enrich_domain: n.enrich_domain || '', is_freemail: !!n.is_freemail,
  city: n.city || '', state: n.state || '', country_code: n.country_code || '',
  context: context
} }];

let pid='';
try{ pid=$('Create CRM Prospect').first().json.id||''; }catch(e){}
if(!pid){ try{ pid=$('Find CRM Prospect').first().json.id||''; }catch(e){} }
let dash='';
try{ dash=String(((($('Find Client Row').first().json||{}).fields)||{})['Dashboard Page ID']||'').trim(); }catch(e){ dash=''; }
let pipeline_url='';
if(pid && dash){
  try{
    const blob=JSON.stringify({pageId:'pagU8C93nMn6vPMTM',rowId:pid});
    const b64=Buffer.from(blob,'utf8').toString('base64').replace(/=+$/,'');
    pipeline_url='https://airtable.com/appQG6dK0FIOhTxOl/'+dash+'?detail='+b64;
  }catch(e){ pipeline_url=''; }
}
return [{ json: { prospect_id: pid, pipeline_url: pipeline_url } }];

// Adapter: the helper's verdict in the shape every node downstream already reads through $('Flatten').
// The judging lives in Enrich and Qualify Lead; this node only renames and carries the thread alongside.
const q = $input.first().json || {};
const n = $('Normalize').first().json || {};
const ft = $('Format Thread').first().json || {};
return [{ json: {
  lead_email: n.lead_email, campaign_id: n.campaign_id, first_name: n.first_name, company_name: q.company_name || n.company_name,
  reply_text: ft.reply_text, thread_context: ft.thread_context,
  custom_qualification_brief: q.brief || '', brief_plain: q.brief_plain || '',
  custom_qualification_status: q.qualification_status || '',
  situation_summary: q.situation_summary || '',
  verdict_reason: q.verdict_reason || '',
  custom_phone: q.phone || '', custom_timezone: q.timezone || '', recommended_action: q.recommended_action || '',
  bizdata: q.bizdata || {},
  base_source: q.base_source || '', base_match: q.base_match || '', base_reason: q.base_reason || ''
} }];

const F = $('Flatten').first().json;
const N = $('Normalize').first().json;
let phoneVal = '', phoneSrc = '';
try { const rp = $('Resolve Phone').first().json || {}; phoneVal = String(rp.phone || '').trim(); phoneSrc = String(rp.phone_source || '').trim(); } catch (e) {}
let B = {};
try { B = $('Flatten').first().json.bizdata || {}; } catch (e) { B = {}; }
let C = {};
try { C = $('Resolve Campaign').first().json || {}; } catch (e) { C = {}; }
let dash = '';
try { dash = String(((($('Find Client Row').first().json || {}).fields) || {})['Dashboard Page ID'] || '').trim(); } catch (e) { dash = ''; }
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clean = (v) => { const s = String(v == null ? '' : v).trim(); return (!s || s.toUpperCase() === 'N/A') ? '' : esc(s); };
const isUuid = (s) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(s || ''));

const companyRaw = F.company_name || N.company_name || 'Unknown';
const tzRaw = String(F.custom_timezone || '').trim();
const tz = clean(tzRaw);
const zmap = {ET:'America/New_York',CT:'America/Chicago',MT:'America/Denver',PT:'America/Los_Angeles',AT:'America/Halifax',AKT:'America/Anchorage',HT:'Pacific/Honolulu',IL:'Asia/Jerusalem',GMT:'Europe/London',BST:'Europe/London','GMT/BST':'Europe/London',CET:'Europe/Berlin',CEST:'Europe/Berlin',AEST:'Australia/Sydney',IST:'Asia/Kolkata'};
let localTime = '';
try { localTime = $now.setZone(zmap[tzRaw] || 'UTC').toFormat('HH:mm'); } catch (e) { localTime = ''; }

const name = clean(((N.first_name || '') + ' ' + (N.last_name || '')).trim());
const title = clean(N.job_title);
const email = clean(N.lead_email);

let phoneLine = '_no number found_';
if (phoneVal) {
  const p = esc(phoneVal);
  if (phoneSrc === 'signature') phoneLine = p + '   ✅ _direct line, from their signature_';
  else if (['supersoniq', 'ai-ark', 'leadmagic', 'prospeo', 'LeadMagic'].includes(phoneSrc)) phoneLine = p + '   ✅ _mobile_';
  else if (phoneSrc.endsWith('-tollfree')) phoneLine = p + '   ⚠️ _switchboard, you will get a receptionist_';
  else phoneLine = p;
}

const who = [];
who.push(name ? ('*' + name + '*' + (title ? '   ' + title : '')) : '*General inbox*   confirm the decision maker');
if (email) who.push(email);
who.push(phoneLine);
who.push('');
const place = [clean(N.city), tz, localTime ? localTime + ' their time' : ''].filter(Boolean).join('   ·   ');
if (place) who.push(place);
const firmo = [clean(B.employees) ? clean(B.employees) + ' staff' : '', clean(B.revenue_range), clean(N.domain)].filter(Boolean).join('   ·   ');
if (firmo) who.push(firmo);

const reply = esc(String(F.reply_text || '').replace(/\s+/g, ' ').trim().slice(0, 900));
const quoted = reply ? '> ' + reply : '> _interested, see thread_';
const brief = esc(String(F.custom_qualification_brief || '').trim());

const blocks = [{ type: 'header', text: { type: 'plain_text', text: ('🔥 new interested qualified lead · ' + companyRaw).slice(0, 150), emoji: true } }];
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: who.join('\n').slice(0, 2900) } });
blocks.push({ type: 'divider' });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*THEY SAID*\n\n' + quoted).slice(0, 2900) } });
if (brief) {
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*WHY THEY QUALIFY*\n\n' + brief).slice(0, 2900) } });
}

let campName = clean(C.campaignName) || clean(N.campaign_name);
if (!campName) { const cid = String(N.campaign_id || '').trim(); if (cid && !isUuid(cid)) campName = clean(cid); }
if (campName) {
  const statBits = [];
  if (C.contacted) statBits.push(esc(C.contacted) + ' contacted');
  if (C.replies !== '' && C.replies != null) statBits.push(esc(C.replies) + ' replies' + (C.replyRate ? ' (' + esc(C.replyRate) + ')' : ''));
  if (C.positives !== '' && C.positives != null) statBits.push(esc(C.positives) + ' positive' + (C.positiveRate ? ' (' + esc(C.positiveRate) + ')' : ''));
  if (C.status) statBits.push(esc(C.status));
  const campLines = ['*WHERE THEY CAME FROM*', '', campName];
  if (statBits.length) campLines.push(statBits.join('   ·   '));
  if (dash && C.campaignRowId) {
    try {
      const blob = JSON.stringify({ pageId: 'pagnDARjFPzq5HclC', rowId: C.campaignRowId });
      const b64 = Buffer.from(blob, 'utf8').toString('base64').replace(/=+$/, '');
      campLines.push('');
      campLines.push('🔗  *<https://airtable.com/appQG6dK0FIOhTxOl/' + dash + '?detail=' + b64 + '|View the campaign>*  copy and live stats');
    } catch (e) {}
  }
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: campLines.join('\n').slice(0, 2900) } });
}

return [{ json: { blocksJson: JSON.stringify({ blocks }) } }];

const sd2=$getWorkflowStaticData('global'); const rs=sd2.runStartedAt||0;
const n=$('Normalize').first().json;
const cv=$('Client Vars').first().json;
const manual=!!cv.manual;
const clientRec=cv.recordId||'';
const name=(n.full_name||'').trim();
const base={
 'Automation':'Enrich & Qualify new lead from PlusVibe',
 'Client': clientRec?[clientRec]:[cv.clientName||''],
 'Run at': $now.toISO(),
 'Records In': 1,
 'Records Out': 1,
 'Target': n.lead_email||'',
 'Trigger': manual?'manual':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000)
};
let f=null; try{ f=$('Flatten').first().json; }catch(e){}
if(!f){
 // Existing-prospect path: Lead in CRM? answered yes, run ended before qualification.
 let exId=''; try{ exId=$('Find CRM Prospect').first().json.id||''; }catch(e){}
 const desc=[
 '**Existing prospect, skipped**',
 '- **Lead:** '+(name?name+' ':'')+'<'+(n.lead_email||'')+'>'+(n.job_title?', '+n.job_title:''),
 '- **Company:** '+(n.company_name||'unknown')+(n.domain?' ('+n.domain+')':''),
 '- **Outcome:** existing prospect already in CRM'+(exId?' ('+exId+')':'')+'; reply not reprocessed, qualification and Slack post skipped'
 ].join('\n').replace('**\n','**\n\n');
 return [{json:Object.assign({'Status':'Succeeded','Errors':0,'Description':desc},base)}];
}
let prospectId='';
try{prospectId=$('Resolve Prospect').first().json.prospect_id||'';}catch(e){}
let created=false;
try{ if($('Create CRM Prospect').first().json.id){created=true;} }catch(e){}
let verdictWritten=false;
try{const v=$('Set CRM Verdict').first().json; if(v&&v.id){verdictWritten=true;}}catch(e){}
let tsWritten=false;
try{const t=$('Set Thread TS').first().json; if(t&&t.id){tsWritten=true;}}catch(e){}
let phoneVal=''; let phoneSource='none';
try{ const rp=$('Resolve Phone').first().json; phoneVal=rp.phone||''; phoneSource=rp.phone_source||'none'; }catch(e){}
const verdict=f.custom_qualification_status||'unknown';
const qualified=verdict!=='out_of_icp';
const campaign=(n.campaign_name?n.campaign_name+(n.campaign_id?' ('+n.campaign_id+')':''):(n.campaign_id||'unknown'));
const failed=[];
