// Decides whether to fire the Waterfall Phones webhook for this lead.
// The waterfall owns the phone write on the contact row; this run only needs
// the resolved number back for the Slack cards and the run log.
// Out-of-ICP leads never trigger paid tiers: they fire only when a direct
// signature number is already in hand (free, instant hit inside the waterfall).
const f = $('Flatten').first().json;
let contactId = '';
try { contactId = $('Create CRM Contact').first().json.id || ''; } catch (e) {}
if (!contactId) {
  try {
    const pf = $('Find CRM Prospect').first().json.fields || {};
    const c = pf.Contacts;
    if (Array.isArray(c) && c.length) contactId = String(c[0] && c[0].id ? c[0].id : c[0]);
  } catch (e) {}
}
let sig = '', sigTf = '';
try { const ft = $('Format Thread').first().json || {}; sig = String(ft.signature_phone || '').trim(); sigTf = String(ft.signature_phone_tollfree || '').trim(); } catch (e) {}
const outOfIcp = f.custom_qualification_status === 'out_of_icp';
const _call = (contactId && (!outOfIcp || sig)) ? 1 : 0;
let reason = '';
if (!contactId) reason = 'no contact row';
else if (outOfIcp && !sig) reason = 'out_of_icp';
return [{ json: { _call, contactId, sig: sig || sigTf, sigIsTF: !sig && !!sigTf, reason } }];

// Parses the Waterfall Phones response back into the shape every downstream
// reader expects ({phone, phone_source}). The waterfall (HTNr5G6vBVkbxsqF) owns
// the tier logic AND the phone write on the contact row; this node only carries
// the verdict forward for the Slack cards, the run log, and the addon payload.
const prep = $('Waterfall Prep').first().json;
const out = { phone: '', phone_source: 'none' };
if (prep._call) {
  const r = $input.first().json;
  let b = r && r.body !== undefined ? r.body : r;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
  if (b && b.phone !== undefined) {
    out.phone = String(b.phone || '');
    out.phone_source = String(b.phone_source || 'none');
  } else {
    // Waterfall unreachable (inactive, timeout, non-JSON): the lead still flows,
    // the phone just stays unresolved. Surfaced in the run log as 'error'.
    out.phone_source = 'error';
  }
} else if (prep.sig) {
  out.phone = prep.sig;
  out.phone_source = prep.sigIsTF ? 'signature-tollfree' : 'signature';
} else if (prep.reason === 'out_of_icp') {
  out.phone_source = 'skipped';
}
return [{ json: out }];

